for k in list(env):
 if k.startswith('GIT_CONFIG_'): env.pop(k)
env.update(GIT_CONFIG_NOSYSTEM='1',GIT_CONFIG_GLOBAL='/tmp/grit-bench-global-config',GIT_CONFIG_SYSTEM='/dev/null',GIT_AUTHOR_NAME='Bench',GIT_AUTHOR_EMAIL='b@example.com',GIT_COMMITTER_NAME='Bench',GIT_COMMITTER_EMAIL='b@example.com')
report={'runs_per_tool':a.runs,'tools':dict(tools),'scenarios':[]}
for plan in plans['scenarios']:
 if a.only and plan['id'] not in a.only.split(','):continue
 cwd=plan['cwd'];env['GRIT_BENCH_CAMPAIGN_CWD']=cwd
 env['GRIT_BENCH_SCRATCH']=str(pathlib.Path(cwd).parent if pathlib.Path(cwd).name.startswith('worktree-run-') else pathlib.Path(cwd))
 if 'clone/checkout' in plan['id']:env['GRIT_BENCH_DAILY_NETWORK_BARE']=cwd+'/remote.git'
 def argv(c):return [c['program']]+c['args']
 def prepare():
