   meta=json.load(open(pathlib.Path(cwd)/'.git/grit-bench-hot-path.json'))
   subprocess.run(['/usr/bin/git','update-ref','refs/heads/'+meta['topic_branch'],meta['pick_commit']],cwd=cwd,env=env,check=True)
   actual=subprocess.check_output(['/usr/bin/git','rev-parse','HEAD'],cwd=cwd,env=env).decode().strip()
   assert actual==meta['main_tip'],(plan['id'],'wrong starting HEAD')

 tree_oracle=None
