use std::path::PathBuf;
use grit_utils::daily::{areas, plan::{DailySetup, DailyPrepare}, runner::{run_ab_bench, AbBenchRequest, BenchArgv, RunPolicy, RunLimits, PostTimedCheck, PreTimedCheck}, remote_fixture::{post_timed_for, pre_timed_for}};
fn main() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let grit = PathBuf::from(&args[1]);
    let output = PathBuf::from(&args[2]);
    let git = PathBuf::from("/usr/bin/git");
    let bench = PathBuf::from("/tmp/grit-4567/grit-bench");
    let selected: Vec<&str> = args[3].split(',').collect();
    let setup = DailySetup {git: &git, grit: &grit, bench: &bench, smoke: false, offline: false};
    let policy = RunPolicy {warmups_per_tool: 1, min_runs_per_tool: 10, max_runs_per_tool: 10, min_total_timed_duration: std::time::Duration::ZERO, scenario_time_budget: std::time::Duration::from_secs(600)};
    let mut rows = vec![];
    for plan in areas::all_daily_plans().into_iter().filter(|p| selected.contains(&p.spec.id)) {
        eprintln!("starting {} with {}", plan.spec.id, grit.display());
        let ctx = (plan.setup)(&setup)?;
        std::env::set_var("GRIT_BENCH_CAMPAIGN_CWD", &ctx.repo);
        if let Some(remote) = &ctx.remote { std::env::set_var("GRIT_BENCH_DAILY_NETWORK_BARE", &remote.bare); }
        if let Some(check) = plan.correctness { check(&ctx)?; }
        let git_cmd = (plan.build_git)(&ctx);
        let grit_cmd = (plan.build_grit)(&ctx);
        let prepare = match (plan.prepare)(&ctx) {
            DailyPrepare::None => None,
            DailyPrepare::Hook(kind) => Some(grit_utils::daily::helpers::prepare_bench_argv(&bench, &git, kind)),
            DailyPrepare::Shell(argv) => Some(argv),
            DailyPrepare::Network(sub) => Some(BenchArgv::new(&bench, [sub, "--git", "/usr/bin/git", "--bare", &ctx.remote.as_ref().unwrap().bare.display().to_string()])),
        };
        let mut prepare = prepare;
        let self_path = std::env::current_exe()?.display().to_string();
        if let Some(command) = prepare.as_mut() {
            if command.program == PathBuf::from(&self_path) { command.program = bench.clone(); }
            for arg in &mut command.args { *arg = arg.replace(&self_path, &bench.display().to_string()); }
        }
        if std::env::var_os("PLAN_ONLY").is_some() {
            let cmd_json = |c: &BenchArgv| serde_json::json!({"program":c.program,"args":c.args});
            rows.push(serde_json::json!({"id":plan.spec.id,"cwd":ctx.repo,"commands":{"git":cmd_json(&git_cmd),"grit":cmd_json(&grit_cmd)},"prepare":prepare.as_ref().map(cmd_json)}));
            std::fs::write(&output, serde_json::to_vec_pretty(&serde_json::json!({"binary":grit,"scenarios":rows}))?)?;
            continue;
        }
        let outcome = run_ab_bench(&AbBenchRequest {
            cwd: &ctx.repo, git: &git_cmd, grit: &grit_cmd, prepare: prepare.as_ref(), policy: &policy, limits: &RunLimits::default(), measure_helper: &bench, correctness: None,
            post_timed: post_timed_for(plan.spec.id).map(|verify|PostTimedCheck{ctx: &ctx,verify}),
            pre_timed: pre_timed_for(plan.spec.id).map(|verify|PreTimedCheck{ctx: &ctx,verify}),
        })?;
        eprintln!("{}: git {:.3} ms; grit {:.3} ms; RSS {} KiB", plan.spec.id, outcome.git.stats.median_ms, outcome.grit.stats.median_ms, outcome.grit.stats.peak_rss_bytes.unwrap_or(0)/1024);
        for (label, command) in [("git", &git_cmd), ("grit", &grit_cmd)] {
            if let Some(prep) = prepare.as_ref() {
                let status = std::process::Command::new(&prep.program).args(&prep.args).current_dir(&ctx.repo).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).status()?;
                anyhow::ensure!(status.success(), "time preparation failed");
            }
            let tag = format!("/tmp/grit-4567/{}-{}-{}.time", plan.spec.id.replace('/', "-").replace('@', "-"), output.file_stem().unwrap().to_string_lossy(), label);
            let status = std::process::Command::new("/usr/bin/time").args(["-v", "-o", &tag]).arg(&command.program).args(&command.args).current_dir(&ctx.repo).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).status()?;
            anyhow::ensure!(status.success(), "time verification failed");
        }
        let cmd_json = |c: &BenchArgv| serde_json::json!({"program":c.program,"args":c.args});
        rows.push(serde_json::json!({"id":plan.spec.id,"cwd":ctx.repo,"git":outcome.git.stats,"grit":outcome.grit.stats,"commands":{"git":cmd_json(&git_cmd),"grit":cmd_json(&grit_cmd)},"prepare":prepare.as_ref().map(cmd_json)}));
        std::fs::write(&output, serde_json::to_vec_pretty(&serde_json::json!({"binary":grit,"runs":10,"scenarios":rows}))?)?;
    }
    Ok(())
}

